/**
 * Options of the smooth graphics shader sources.
 * @internal
 */
export interface SmoothShaderSourceOptions {
    /** Max batch textures */
    maxTextures: number;
    /** Whether the shader uses the local uniforms, to draw a context that isn't batched */
    localUniforms?: boolean;
    /** Whether the vertices carry a texture coordinate matrix (the 'smoothTextured' vertex format) */
    textured?: boolean;
    /** Declarations added to the fragment shader (uniforms in GLSL, bind groups in WGSL) */
    fragmentHeader?: string;
    /** Code run in the fragment shader after the coverage is computed, it can change `alpha` */
    fragmentAlpha?: string;
}
/**
 * Generates the GLSL sources of a smooth graphics shader.
 * @param options - The shader options
 * @returns The vertex and fragment sources
 * @internal
 */
export declare function generateSmoothGlSource(options: SmoothShaderSourceOptions): {
    vertex: string;
    fragment: string;
};
/**
 * Generates the WGSL source of a smooth graphics shader, with the `mainVertex` and `mainFragment` entry points.
 * @param options - The shader options
 * @returns The WGSL source
 * @internal
 */
export declare function generateSmoothWgslSource(options: SmoothShaderSourceOptions): string;
